<?php require 'inc.php';start('My account');$mon=$_GET['m']??date('Y-m');$m=$_SESSION['member'];$c=calc($mon,$m)[0];?>
<div class="card"><form class="row" method="get"><div><label>Month</label><input type="month" name="m" value="<?=e($mon)?>"></div><button>Show</button></form></div>
<div class="card kpis"><div class="kpi">Litres accepted<b><?=$c['litres']?></b></div><div class="kpi">Gross<b>UGX <?=n($c['gross'])?></b></div><div class="kpi">Deductions<b>UGX <?=n($c['ded'])?></b></div><div class="kpi">Net pay<b>UGX <?=n($c['net'])?></b></div></div>
<div class="card wrap"><h3>My deliveries</h3><table><tr><th>Date</th><th>Litres</th><th>Fat %</th><th>Grade</th><th>Result</th></tr><?php foreach(q('SELECT d.delivery_date,d.litres,t.fat_percent,t.grade,t.result FROM delivery d LEFT JOIN quality_test t USING(delivery_id) WHERE d.member_id=? ORDER BY d.delivery_id DESC LIMIT 30',[$m]) as $d)echo '<tr><td>'.$d['delivery_date'].'</td><td>'.$d['litres'].'</td><td>'.($d['fat_percent']??'-').'</td><td>'.($d['grade']??'-').'</td><td>'.($d['result']?:'Pending test').'</td></tr>';?></table></div><?php done();
